-- ====== FINAL SCHEMA ======

-- Regions Catalog
DROP TABLE IF EXISTS public.regiones CASCADE;
CREATE TABLE public.regiones (
  region_id SMALLINT PRIMARY KEY,
  nombre    TEXT NOT NULL
);

-- Provinces Catalog
DROP TABLE IF EXISTS public.provincias CASCADE;
CREATE TABLE public.provincias (
  provincia_id SMALLINT PRIMARY KEY,
  region_id    SMALLINT NOT NULL REFERENCES public.regiones(region_id) ON UPDATE CASCADE ON DELETE RESTRICT,
  nombre       TEXT NOT NULL
);

-- Load Catalogs from Staging
SELECT CAST(LPAD(TRIM(cod_reg),2,'0') AS SMALLINT) AS region_id,
       TRIM(nom_reg)
FROM public.ipm_e_region_stage
ON CONFLICT (region_id) DO UPDATE SET nombre = EXCLUDED.nombre;

SELECT CAST(LPAD(TRIM(p.cod_prv),3,'0') AS SMALLINT) AS provincia_id,
       CAST(LPAD(TRIM(p.cod_reg),2,'0') AS SMALLINT) AS region_id,
       TRIM(p.nom_prv) AS nombre
FROM public.ipm_e_provincia_stage p
ON CONFLICT (provincia_id) DO UPDATE
SET nombre = EXCLUDED.nombre,
    region_id = EXCLUDED.region_id;

-- Final Municipalities Table with Normalized Geometry
DROP TABLE IF EXISTS public.comunas CASCADE;
CREATE TABLE public.comunas (
  codigo             TEXT PRIMARY KEY,                 -- 5 digit code
  nombre             TEXT NOT NULL,
  nombre_norm        TEXT,
  google             TEXT,
  region_id          SMALLINT NOT NULL REFERENCES public.regiones(region_id) ON UPDATE CASCADE,
  provincia_id       SMALLINT NOT NULL REFERENCES public.provincias(provincia_id) ON UPDATE CASCADE,
  cod_csv            TEXT,
  cod_antiguo_flag   BOOLEAN,
  observaciones      TEXT,
  ciudad_juzgado     TEXT,
  ciudad_conservador TEXT,
  ciudad_bom         TEXT,
  juzgado_id         INTEGER,
  boletin_id         INTEGER,
  sernageomin_id     INTEGER,
  conservador_id     INTEGER,
  geom               geometry(MultiPolygon,4326) NOT NULL
);

CREATE INDEX IF NOT EXISTS comunas_geom_gix         ON public.comunas USING GIST (geom);
CREATE INDEX IF NOT EXISTS comunas_nombre_trgm      ON public.comunas USING GIN (nombre gin_trgm_ops);
CREATE INDEX IF NOT EXISTS comunas_nombre_norm_trgm ON public.comunas USING GIN (nombre_norm gin_trgm_ops);

-- ETL: Load from Staging + Geometry Cleanup
  codigo, nombre, nombre_norm, google,
  region_id, provincia_id, cod_csv, cod_antiguo_flag,
  observaciones, ciudad_juzgado, ciudad_conservador, ciudad_bom,
  juzgado_id, boletin_id, sernageomin_id, conservador_id, geom
)
SELECT
  TRIM(c.codigo) AS codigo,
  TRIM(c.nombre) AS nombre,
  REGEXP_REPLACE(LOWER(unaccent(TRIM(c.nombre))), '[[:space:]]+', ' ', 'g') AS nombre_norm,
  NULLIF(TRIM(c.google),'') AS google,
  CAST(LPAD(TRIM(c.cod_reg),2,'0') AS SMALLINT) AS region_id,
  CAST(LPAD(TRIM(c.cod_prv),3,'0') AS SMALLINT) AS provincia_id,
  NULL::TEXT AS cod_csv,
  CASE WHEN c.cod_antiguo = 1 THEN TRUE ELSE FALSE END AS cod_antiguo_flag,
  NULLIF(TRIM(c.observaciones),''),
  NULLIF(TRIM(c.ciudad_juzgado),''),
  NULLIF(TRIM(c.ciudad_conservador),''),
  NULLIF(TRIM(c.ciudad_bom),''),
  c.juzgado_id, c.boletin_id, c.sernageomin_id, c.conservador_id,
  ST_Multi(
    ST_CollectionExtract(
      ST_MakeValid(
        CASE
          WHEN ST_SRID(c.geom) IS NULL OR ST_SRID(c.geom)=0 THEN ST_SetSRID(c.geom,4326)
          WHEN ST_SRID(c.geom)<>4326 THEN ST_Transform(c.geom,4326)
          ELSE c.geom
        END
      ), 3  -- 3=POLYGON
    )
  ) AS geom
FROM public.comunas_stage c
ON CONFLICT (codigo) DO NOTHING;

-- Data Enrichment: Link details from CSV codes
UPDATE public.comunas c
SET cod_csv = s.cod_csv
FROM public.ipm_e_comuna_stage s
WHERE TRIM(s.cod_com) = c.codigo
  AND NULLIF(TRIM(s.cod_csv),'') IS NOT NULL
  AND (c.cod_csv IS DISTINCT FROM s.cod_csv);

-- Alias Table for Legacy Codes
DROP TABLE IF EXISTS public.comuna_codigo_alias;
CREATE TABLE public.comuna_codigo_alias (
  alias_id      BIGSERIAL PRIMARY KEY,
  codigo_alias  TEXT NOT NULL,
  codigo_actual TEXT NOT NULL REFERENCES public.comunas(codigo) ON UPDATE CASCADE,
  alias_tipo    TEXT NOT NULL CHECK (alias_tipo IN ('antiguo','externo','csv','otro')),
  valido_desde  DATE,
  valido_hasta  DATE,
  fuente        TEXT,
  nota          TEXT
);
CREATE INDEX IF NOT EXISTS idx_alias_codigo   ON public.comuna_codigo_alias (codigo_alias);
CREATE INDEX IF NOT EXISTS idx_alias_actual   ON public.comuna_codigo_alias (codigo_actual);

SELECT DISTINCT TRIM(s.cod_com), TRIM(s.cod_com), 'antiguo', 'ipm_e_comuna', NULLIF(TRIM(s.observaciones),'')
FROM public.ipm_e_comuna_stage s
WHERE s.cod_antiguo = 1
  AND EXISTS (SELECT 1 FROM public.comunas c WHERE c.codigo = TRIM(s.cod_com));

SELECT DISTINCT TRIM(s.cod_csv), TRIM(s.cod_com), 'csv', 'ipm_e_comuna', 'Administrative Short Code'
FROM public.ipm_e_comuna_stage s
WHERE s.cod_csv IS NOT NULL AND s.cod_csv <> ''
  AND EXISTS (SELECT 1 FROM public.comunas c WHERE c.codigo = TRIM(s.cod_com));

-- (Optional) Spatial Bounding Box Acceleration
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='comunas' AND column_name='bbox'
  ) THEN
    ALTER TABLE public.comunas ADD COLUMN bbox geometry(Polygon,4326);
    UPDATE public.comunas SET bbox = ST_Envelope(geom);
    CREATE INDEX IF NOT EXISTS idx_comunas_bbox_gist ON public.comunas USING GIST (bbox);
  END IF;
END$$;
